"""Beginner explanations for page free and metadata mapping preparation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1757': ('반납한 책상에는 이제 쓰면 안 된다는 표시가 필요해요. 메모리 검사 도구도 반납된 공간을 다시 읽는 실수를 찾기 위해 검사표에 표시를 남겨요.', '메모리 반납 표시의 범위와 해제 후 사용을 구별합니다.', 'page_size(page)가 8192를 돌려준다고 가정하고 검사 범위에 8192바이트를 적으세요. order에서 새로 계산하는 화살표는 그리지 마세요.', ['kmsan_free_page는 메모리를 해제할 때 검사 정보를 바꾸는 함수예요. 해제는 사용하던 메모리를 반납하는 일이에요. 반납한 자리를 계속 쓰는 실수를 use-after-free, 줄여서 UAF라고 불러요.', 'KMSAN이 꺼져 있거나 도구 자신의 처리 중이면 먼저 돌아가요. 그렇지 않으면 enter_runtime으로 도구 처리에 들어가고, 검사 표시를 바꾼 뒤 leave_runtime으로 나와요.', 'poison은 여기서 실제 메모리에 독을 넣는다는 말이 아니에요. shadow 검사표에 아직 안전하게 읽을 수 없는 상태를 표시하는 일이에요. 실제 페이지를 다른 사용자가 쓰도록 반납하는 일과 검사표를 바꾸는 일은 구별해야 해요.', '시작 주소는 page_address(page), 길이는 page_size(page)로 얻어요. 인자로 order를 받지만 이 함수 본문은 그 값을 사용하지 않아요. 앞의 할당 함수처럼 PAGE_SIZE 곱하기 2의 order승으로 직접 계산한다고 추측하면 안 돼요.', '예를 들어 page_size(page)의 결과가 8192이면 표시할 범위는 8192바이트예요. 중요한 것은 인자 이름이 아니라 실제로 길이 자리에 전달하는 식이에요. page_size가 알려 주는 페이지 크기를 따라가요.', 'KMSAN_POISON_CHECK와 KMSAN_POISON_FREE를 |로 합쳐 전달해요. |는 여기서 두 옵션을 함께 켜는 비트 연산이에요. CHECK는 검사 정보가 없는 범위의 진단에, FREE는 해제 뒤 사용과 관련된 원인 표시에 쓰여요. GFP_KERNEL은 원인 기록 등에 필요한 메모리 요청 조건으로 전달돼요.'], [('이 함수가 검사 표시를 바꿀 길이는 어디서 얻나요?', ['order만 보고 이 함수에서 직접 계산해요', 'page_size(page)의 결과를 사용해요'], '정답은 두 번째예요. poison 함수의 길이 인자에 page_size(page)가 있어요. order는 받지만 본문에서는 사용하지 않아요.'), ('poison 함수에 함께 전달하는 두 옵션은 무엇인가요?', ['CHECK와 FREE예요', '검사를 끄는 옵션 하나뿐이에요'], '정답은 첫 번째예요. CHECK | FREE는 두 표시를 함께 전달해요. 검사 범위의 진단과 해제 관련 원인 표시에 연결되며, 실제 페이지 반납 자체와는 다른 작업이에요.')]), 'os1758': ('주소 안내판을 만들기 전에 어느 페이지를 연결할지 목록부터 준비해요. 실제 내용용 목록을 보고 검사표용 목록 두 개를 따로 만드는 과정이에요.', '주소 연결을 위한 임시 목록과 보호 설정을 이해합니다.', '데이터 페이지 A와 B를 그리고 각각에서 shadow 목록과 origin 목록으로 화살표를 두 개씩 그리세요.', ['vmap은 여러 페이지를 가상 주소로 찾아갈 수 있도록 연결하는 작업이에요. 가상 주소는 프로그램이 사용하는 주소이고, 매핑은 그 주소를 실제 페이지에 연결하는 관계예요. 이 함수는 KMSAN 검사 정보의 연결을 준비해요.', 'shadow는 준비 상태표, origin은 원인 정보표예요. KMSAN이 꺼져 있으면 바로 0을 반환해요. 또한 vmalloc_meta로 구한 shadow 시작 주소가 0이면 작업 없이 0을 반환해요. 반환값 0만 보고 반드시 새 연결을 만들었다고 해석하면 안 돼요.', 'nr = (end - start) / PAGE_SIZE는 범위 안 페이지 개수를 구해요. end는 범위 바로 다음 주소예요. 길이가 8192바이트이고 페이지가 4096바이트면 nr은 2예요. 호출자가 올바른 범위와 페이지 배열을 제공한다는 조건으로 읽어요.', 'kcalloc으로 s_pages와 o_pages라는 임시 배열을 각각 만들어요. 배열은 번호를 붙인 칸들의 모음이에요. 여기의 칸은 페이지 내용 전체를 담지 않고 해당 페이지를 가리키는 포인터를 담아요. 두 배열이 생겼다고 새 데이터 페이지 두 묶음을 만든 것은 아니에요.', '반복문에서 pages[i]의 shadow 연결을 s_pages[i]에, origin 연결을 o_pages[i]에 넣어요. 데이터 페이지가 A, B라면 shadow 목록은 A의 shadow와 B의 shadow, origin 목록은 A의 origin과 B의 origin을 담아요.', 'prot는 접근 권한 등을 정하는 보호 설정이에요. 이 함수는 받은 값을 PAGE_KERNEL로 바꿔 검사 정보 연결에 사용해요. 페이지 크기 방식을 나타내는 page_shift 인자는 아래 연결 함수에 그대로 전달해요. 데이터 연결의 설정과 검사 정보 연결의 설정을 구별하세요.'], [('검사 정보 연결에 쓸 prot는 어떻게 정하나요?', ['호출자가 준 값을 항상 그대로 써요', '이 함수에서 PAGE_KERNEL로 바꿔요'], '정답은 두 번째예요. prot = PAGE_KERNEL이라는 대입이 있어요. 대입 뒤의 연결 요청에는 바뀐 값이 쓰여요.'), ('새로 만드는 임시 포인터 목록은 무엇인가요?', ['shadow용 하나와 origin용 하나예요', '실제 데이터 전체를 복사하는 목록 하나예요'], '정답은 첫 번째예요. s_pages와 o_pages를 따로 만들어요. 각 칸에는 검사 페이지를 가리키는 포인터가 들어가며, 데이터 내용을 통째로 복사하는 단계가 아니에요.')]), 'os1759': ('새 주소 안내판을 달았어도 예전에 외워 둔 길을 계속 따라가면 잘못된 곳에 갈 수 있어요. 연결을 바꾼 뒤에는 CPU가 기억한 주소 정보도 맞춰 주어야 해요.', '두 검사 정보의 주소 연결과 그 뒤의 TLB·캐시 처리를 순서대로 읽습니다.', '진입 → shadow 연결 → origin 연결 → 종료 → TLB 두 범위 처리 → 캐시 두 범위 처리 → 임시 목록 반납을 적어 보세요.', ['이 수업은 두 임시 목록을 만들고 주소 연결도 모두 성공한 경우를 다뤄요. 먼저 kmsan_enter_runtime을 호출하고 shadow 페이지들을 연결해요. 그다음 origin 페이지들을 연결해요.', '__vmap_pages_range_noflush의 결과는 mapped에 저장해요. 여기서는 0이 성공이에요. 0이 아니면 오류 처리로 가므로, 변수 이름만 보고 연결한 페이지 개수가 들어 있다고 생각하면 안 돼요.', '두 연결이 모두 성공하면 kmsan_leave_runtime을 호출해 도구 처리에서 나와요. 정상적으로 0에서 진입했다면 상태가 0 → 1 → 0으로 돌아와요. 그 뒤에 TLB와 캐시 관련 함수가 실행돼요.', 'TLB는 CPU가 주소 변환 결과를 빨리 찾으려고 기억해 두는 곳이에요. 페이지 연결을 바꾼 뒤 예전 변환 결과가 남아 있으면 문제가 될 수 있어요. 그래서 shadow 범위와 origin 범위에 flush_tlb_kernel_range를 각각 호출해요.', '캐시는 접근을 빠르게 하려고 정보를 가까운 곳에 보관하는 장치예요. 새 가상 주소 연결에 맞게 필요한 캐시 처리를 하도록 두 범위에 flush_cache_vmap도 각각 호출해요. 실제로 필요한 세부 작업은 CPU 기종의 구현에 따라 달라질 수 있어요.', '마지막 ret 위치에서는 임시 포인터 배열 두 개를 kfree로 반납하고 err를 반환해요. 성공 경로의 err는 0이에요. 목록을 반납하는 것과 연결한 검사 페이지 자체를 없애는 것은 달라요. 함수 이름에 noflush가 있어도 이 본문에서 호출하는 네 flush 함수를 직접 확인하세요.'], [('이 코드가 부르는 페이지 연결 함수는 성공했을 때 무엇을 반환하나요?', ['연결한 페이지 수를 항상 양수로 반환해요', '0을 반환해요'], '정답은 두 번째예요. if (mapped)는 0이 아닌 결과를 오류로 처리해요. 각 함수의 성공값은 실제 조건문과 함께 읽어야 해요.'), ('정상적으로 runtime 상태 0에서 시작했다면 성공 경로의 flush 시점은 어떤 상태인가요?', ['leave_runtime을 거쳐 다시 0인 상태예요', '아직 진입 상태 1이고 종료 호출 전이에요'], '정답은 첫 번째예요. 두 연결 뒤에 leave_runtime이 있고 그다음 flush 호출들이 있어요. 시작 상태가 정상이라는 조건까지 함께 기억하세요.')]), 'os1760': ('상자를 두 개 빌려야 하는데 하나만 빌린 뒤 다음 상자를 구하지 못했어요. 일을 계속할 수 없다면 이미 빌린 상자도 돌려줘야 해요.', '부분적으로 성공한 메모리 요청을 실패 경로에서 정리하는 이유를 이해합니다.', 'shadow 목록 성공·origin 목록 실패와 그 반대의 표를 그리고, 각 경우 실제로 반납할 목록에 동그라미를 치세요.', ['이 함수는 shadow 페이지 목록과 origin 페이지 목록을 따로 요청해요. kcalloc은 필요한 메모리를 구하지 못하면 NULL을 반환해요. NULL은 여기서 사용할 목록이 없다는 표시예요.', '두 요청을 먼저 실행한 뒤 !s_pages || !o_pages를 확인해요. !는 없다는 조건을 만들고 ||는 둘 중 하나라도 참이면 참이라는 뜻이에요. 따라서 첫 요청이 실패했더라도 두 번째 요청까지 이미 시도한 상태예요.', '하나라도 없으면 err에 -ENOMEM을 넣어요. ENOMEM은 메모리를 확보하지 못했다는 오류 종류예요. goto ret는 ret라고 표시한 정리 위치로 이동하라는 뜻이에요. 성공을 뜻하는 0과 구별해야 해요.', 'ret에서는 kfree(s_pages)와 kfree(o_pages)를 모두 호출해요. kfree(NULL)은 반납할 대상이 없으므로 안전하게 지나가요. 그래서 성공한 목록만 실제로 반납하고 실패한 쪽은 아무 메모리도 반납하지 않아요.', '예를 들어 첫 목록 성공, 둘째 실패라면 첫 목록을 반납해요. 첫째 실패, 둘째 성공이면 둘째를 반납해요. 둘 다 실패했으면 실제로 반납할 목록도 없어요. 한쪽만 성공한 자원을 잊으면 쓰지 않는 메모리가 계속 남는 누수가 생길 수 있어요.', '이 실패 검사는 enter_runtime보다 앞에 있어요. 따라서 정상 상태 0에서 호출했다면 도구 처리에 진입하지 않은 채 끝나요. 뒤의 주소 연결 실패와 같은 ret로 가더라도, 그 전에 무엇을 실행했는지는 다를 수 있어요. 정리 위치의 이름만 보고 모든 오류 상태가 같다고 생각하면 안 돼요.'], [('임시 목록 중 하나를 만들지 못하면 어떤 결과를 돌려주나요?', ['목록이 없어도 항상 성공 0이에요', '메모리 확보 실패를 뜻하는 -ENOMEM이에요'], '정답은 두 번째예요. 조건문에서 err = -ENOMEM을 설정하고 정리한 뒤 err를 반환해요. 작업을 생략하고 0을 반환하는 앞쪽 조건과는 다른 경로예요.'), ('첫 목록은 만들었지만 둘째 목록을 만들지 못하면 첫 목록은 어떻게 되나요?', ['ret에서 kfree로 반납해요', '그대로 두고 주소를 잊어버려요'], '정답은 첫 번째예요. ret에는 두 목록을 각각 반납하는 호출이 있어요. NULL인 둘째는 실제 반납 없이 지나가고, 성공한 첫째는 반납해 누수를 막아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_435.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
